def count_stack_exterminable_subarrays(n, arr):
    stack = []
    count = 0

    for i in range(n):
        if not stack or stack[-1] != arr[i]:
            stack.append(arr[i])
        else:
            stack.pop()

        if not stack:
            count += 1

    return count

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    q = int(data[0])
    index = 1
    results = []

    for _ in range(q):
        n = int(data[index])
        index += 1
        arr = list(map(int, data[index:index + n]))
        index += n

        results.append(count_stack_exterminable_subarrays(n, arr))

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
